export default function ServicesSelector({ services, setServices }) {

  if (!services || Object.keys(services).length === 0) {
    return <div>Loading services...</div>;
  }

  const toggle = (svc) => {
    setServices(prev => ({
      ...prev,
      [svc]: !prev[svc]
    }));
  };

  const selectAll = () => {
    const allServices = {};
    Object.keys(services).forEach(svc => {
      allServices[svc] = true;
    });
    setServices(allServices);
  };

  const selectNone = () => {
    const allServices = {};
    Object.keys(services).forEach(svc => {
      allServices[svc] = false;
    });
    setServices(allServices);
  };

  const allSelected = Object.values(services).every(val => val === true);
  const noneSelected = Object.values(services).every(val => val === false);

  return (
    <div>
      <h3>Services</h3>

      <div style={{ marginBottom: "10px" }}>
        <button 
          onClick={selectAll} 
          disabled={allSelected}
          style={{ 
            marginRight: "10px", 
            padding: "5px 10px",
            backgroundColor: allSelected ? "#ccc" : "#007bff",
            color: "white",
            border: "none",
            borderRadius: "4px",
            cursor: allSelected ? "not-allowed" : "pointer"
          }}
        >
          Select All
        </button>
        <button 
          onClick={selectNone} 
          disabled={noneSelected}
          style={{ 
            padding: "5px 10px",
            backgroundColor: noneSelected ? "#ccc" : "#dc3545",
            color: "white",
            border: "none",
            borderRadius: "4px",
            cursor: noneSelected ? "not-allowed" : "pointer"
          }}
        >
          Select None
        </button>
      </div>

      {Object.keys(services).map(svc => (
        <div key={svc}>
          <input
            type="checkbox"
            checked={services[svc] || false}
            onChange={() => toggle(svc)}
          />
          {svc}
        </div>
      ))}
    </div>
  );
}
